CREATE TABLE IF NOT EXISTS `sessions` (`tokenHash` varchar(64) NOT NULL,`userId` int NOT NULL,`expiresAt` timestamp NOT NULL,PRIMARY KEY (`tokenHash`),FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `inscricoesBatismo` (`id` int AUTO_INCREMENT NOT NULL,`nome` varchar(255) NOT NULL,`dataNascimento` varchar(10) NOT NULL,`celula` varchar(255) NOT NULL,`telefone` varchar(20) NOT NULL,`motivacao` text NOT NULL,`status_batismo` enum('pendente','aprovado','rejeitado') NOT NULL DEFAULT 'pendente',`dataProcessamento` timestamp NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `anotacoesDevocional` (`id` int AUTO_INCREMENT NOT NULL,`userId` int NOT NULL,`livro` varchar(100) NOT NULL,`capitulo` int NOT NULL,`texto` text NOT NULL,`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `avisoImportante` (`id` int AUTO_INCREMENT NOT NULL,`titulo` varchar(255) NOT NULL,`mensagem` text NOT NULL,`ativo` int NOT NULL DEFAULT 1,`dataExpiracao` varchar(50),`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `aniversariantes` (`id` int AUTO_INCREMENT NOT NULL,`nome` varchar(255) NOT NULL,`dataNascimento` varchar(10) NOT NULL,`celula` varchar(255),`telefone` varchar(20),`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `contribuicoes` (`id` int AUTO_INCREMENT NOT NULL,`userId` int NOT NULL,`nome` varchar(255) NOT NULL,`valor` varchar(20) NOT NULL,`tipo` varchar(50) NOT NULL,`data` varchar(50) NOT NULL,`comprovanteUrl` varchar(500),`status_contribuicao` enum('pendente','confirmado','rejeitado') NOT NULL DEFAULT 'pendente',`createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`));
ALTER TABLE `configEscolaCrescimento` ADD COLUMN IF NOT EXISTS `descricaoConecte` text;
ALTER TABLE `configEscolaCrescimento` ADD COLUMN IF NOT EXISTS `descricaoLidere1` text;
ALTER TABLE `configEscolaCrescimento` ADD COLUMN IF NOT EXISTS `descricaoLidere2` text;
ALTER TABLE `configEscolaCrescimento` ADD COLUMN IF NOT EXISTS `descricaoAvance` text;
ALTER TABLE `eventos` ADD COLUMN IF NOT EXISTS `especial` boolean NOT NULL DEFAULT false;
ALTER TABLE `inscricoesEventos` ADD COLUMN IF NOT EXISTS `status` varchar(50) NOT NULL DEFAULT 'confirmado';
ALTER TABLE `noticias` ADD COLUMN IF NOT EXISTS `imagemUrl` varchar(500);
